import React, { useState, useEffect, useRef } from 'react'
import logoMacau from '../Logo MACAU.png'

const API_BASE_URL = (import.meta.env.VITE_API_BASE_URL || 'http://127.0.0.1:8011').replace(/\/$/, '')
const API_BASE_FALLBACKS = Array.from(new Set([
  API_BASE_URL,
  'http://127.0.0.1:8001',
  'http://localhost:8001',
  'http://127.0.0.1:8011',
  'http://localhost:8011'
].map((item) => String(item || '').replace(/\/$/, ''))))
const LEGACY_API_BASE_URLS = [
  'http://localhost:8001',
  'http://127.0.0.1:8001',
  'http://127.0.0.1:8011',
  'http://localhost:8011'
]

const CAREER_FALLBACK = [
  'Ingeniería Mecatrónica',
  'Ingeniería en Sistemas',
  'Licenciatura en Sistemas',
  'Tecnicatura Universitaria en Ciencia de Datos',
  'Tecnicatura Universitaria en Desarrollo Web'
]

const isTechnicalCareerName = (careerValue) => /tecnicatura/i.test(String(careerValue || '').trim())
const normalizeTerminologyText = (input) => {
  const value = String(input || '')
  if (!value) return value
  const matchCase = (original, replacement) => {
    if (!original) return replacement
    if (original === original.toUpperCase()) return replacement.toUpperCase()
    if (original[0] === original[0].toUpperCase()) return replacement.charAt(0).toUpperCase() + replacement.slice(1)
    return replacement
  }

  return value
    .replace(/\bmateria(s)?\b/gi, (m) => matchCase(m, 'asignatura'))
    .replace(/\bprofesor(a|es|as)?\b/gi, (m) => matchCase(m, 'docente'))
    .replace(/\balumno(s|as)?\b/gi, (m) => matchCase(m, 'estudiante'))
}

const getLearningOutcomeLabelsByCareer = (careerValue) => {
  const technical = isTechnicalCareerName(careerValue)
  return technical
    ? {
      sectionTitle: 'Objetivos de Aprendizaje',
      shortPlural: 'Objetivos',
      shortSingular: 'Objetivo',
      shortIndexPrefix: 'Obj'
    }
    : {
      sectionTitle: 'Resultados de Aprendizaje',
      shortPlural: 'RA',
      shortSingular: 'Resultado de Aprendizaje',
      shortIndexPrefix: 'RA'
    }
}

/** Inline edit row used inside the Admin Carreras table. */
const AdminCareerInlineEdit = ({ career, apiBase, onSaved, onCancel }) => {
  const [name, setName] = React.useState(career.name)
  const [saving, setSaving] = React.useState(false)
  const [error, setError] = React.useState('')

  const save = async () => {
    const trimmed = name.trim()
    if (!trimmed) { setError('El nombre no puede estar vacío.'); return }
    setSaving(true); setError('')
    try {
      const res = await fetch(`${apiBase}/careers/${career.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: trimmed })
      })
      if (res.status === 409) { setError('Ya existe una carrera con ese nombre.'); return }
      if (!res.ok) { setError('Error al guardar.'); return }
      onSaved()
    } catch { setError('Error de red.') }
    finally { setSaving(false) }
  }

  return (
    <div>
      <div style={{ display: 'flex', gap: '8px', alignItems: 'center', flexWrap: 'wrap' }}>
        <input
          style={{ border: '1px solid #90caf9', borderRadius: '6px', padding: '4px 8px', fontSize: '14px', flex: 1, minWidth: '200px' }}
          value={name}
          onChange={e => setName(e.target.value)}
          onKeyDown={e => { if (e.key === 'Enter') save(); if (e.key === 'Escape') onCancel() }}
          autoFocus
        />
        <button
          style={{ background: '#1976d2', color: '#fff', border: 'none', borderRadius: '6px', padding: '4px 12px', fontSize: '13px', cursor: saving ? 'not-allowed' : 'pointer' }}
          disabled={saving}
          onClick={save}
        >
          {saving ? '...' : '✓ Guardar'}
        </button>
        <button
          style={{ background: '#90a4ae', color: '#fff', border: 'none', borderRadius: '6px', padding: '4px 10px', fontSize: '13px', cursor: 'pointer' }}
          onClick={onCancel}
        >
          Cancelar
        </button>
      </div>
      {error && <div style={{ color: '#c62828', fontSize: '12px', marginTop: '4px' }}>{error}</div>}
    </div>
  )
}

