                                              borderRight: '1px solid #eee',
                                              background: check.ok ? 'rgba(56, 142, 60, 0.08)' : 'rgba(211, 47, 47, 0.1)',
                                              color: check.ok ? '#1b5e20' : '#b00020',
                                              fontWeight: 700,
                                              cursor: check.ok ? 'default' : 'help'
