                          const otherTerms = year.terms.filter((t) => t.name !== 'Anual')
                          const firstTerm = otherTerms.find((t) => t.name === '1er Cuatrimestre')
                          const secondTerm = otherTerms.find((t) => t.name === '2do Cuatrimestre')
